def note_for(sit_no, code):
    base = M[code][4]
    if code == "MSK":
        if sit_no in (9, 10, 14, "12Б"):
            return "Форма для передачи МСК. При использовании МСК в рамках ипотечного кредитования условие о достижении ребёнком 3-х лет НЕ применяется."
        return "Форма для передачи МСК. Перечисление возможно, если младшему ребёнку Покупателя на момент заключения ОДКП 3 года или более."
    if code == "ZALOG_POK" and sit_no in (7, 8, 9, 10):
        return base + " [РЕКОМЕНДУЕМОЕ ДОПОЛНЕНИЕ: в исходных банковских формах присутствует; в текущей практике 1–10 мог опускаться — решить единообразно.]"
    if code == "NO_ZALOG_PROD":
        return "[ОПЦИОНАЛЬНО] " + base
    return base

